from collections import Counter

def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    diag=Counter()
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v and r>=3 and c>=3:
                diag[r+c, v]+=1
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c]=1
            elif r == 2 or c == 2:
                out[r][c]=4
            else:
                choices=[(n,v) for (s,v),n in diag.items() if s==r+c]
                if choices:
                    out[r][c]=max(choices)[1]
    return out

